<?php
/** Auto Post draft candidate generation service. @package OBEngine\AutoPost */
namespace OBEngine\AutoPost;

use OBEngine\Activity\Activity_Action;
use OBEngine\Activity\Activity_Logger;
use OBEngine\Activity\Activity_Object_Type;
use OBEngine\AI\AI_Engine;
use OBEngine\AI\AI_Response;
use OBEngine\AI\AI_Task_Type;
use OBEngine\AI\Structured_Output;
use OBEngine\Library\Library_Item;
use OBEngine\Library\Library_Repository;
use OBEngine\Library\Library_Status;
use OBEngine\Library\Library_Type;
use WP_Error;

defined( 'ABSPATH' ) || exit;

final class Auto_Post_Draft_Service {
	private $engine; private $library_repository; private $logger;
	public function __construct( AI_Engine $engine = null, Library_Repository $library_repository = null, Activity_Logger $logger = null ) { $this->engine = $engine ?: new AI_Engine(); $this->library_repository = $library_repository ?: new Library_Repository(); $this->logger = $logger ?: new Activity_Logger(); }
	public function generate_draft( array $data ) { $data = $this->validate_data( $data ); if ( empty( $data['auto_post_plan_library_item_id'] ) ) { return $this->fail( 'Auto Post Plan is required.', array() ); } $plan_item = $this->library_repository->get( $data['auto_post_plan_library_item_id'] ); if ( ! $plan_item instanceof Library_Item || Library_Type::AUTO_POST_PLAN !== $plan_item->get_type() ) { return $this->fail( 'Select a valid Auto Post Plan Library item.', array( 'auto_post_plan_library_item_id' => $data['auto_post_plan_library_item_id'] ) ); } $data['plan_title'] = $plan_item->get_title(); $data['source_label'] = '' !== $plan_item->get_source_label() ? $plan_item->get_source_label() : 'Auto Post Plan'; $plan_payload = $this->extract_plan_payload( $data['auto_post_plan_library_item_id'] ); $response = $this->engine->run( $this->build_ai_task_data( $data, $plan_payload ) ); if ( ! $response->is_success() ) { $this->logger->failed( Activity_Action::AUTO_POST_DRAFT_FAILED, array( 'object_type' => Activity_Object_Type::AUTO_POST, 'object_label' => $plan_item->get_title(), 'message' => 'Auto Post draft generation failed.', 'context' => array( 'auto_post_plan_library_item_id' => $data['auto_post_plan_library_item_id'] ) ) ); return array( 'success' => false, 'message_public' => 'Auto Post draft generation failed. Review provider settings and try again.' ); } $draft = $this->build_auto_post_draft( $response, $data, $plan_payload ); if ( '' === $draft->get_title() && '' === trim( wp_strip_all_tags( $draft->get_content() ) ) ) { return $this->fail( 'Auto Post draft generation returned no usable draft content.', array( 'auto_post_plan_library_item_id' => $data['auto_post_plan_library_item_id'] ) ); } $library_data = $this->build_library_data( $draft, $data ); $created = $this->library_repository->create( $library_data ); if ( $created instanceof WP_Error || ! $created ) { return array( 'success' => false, 'message_public' => 'Auto Post draft could not be saved to Library.' ); } $response_data = $response->to_array(); $this->logger->success( Activity_Action::AUTO_POST_DRAFT_CREATED, array( 'object_type' => Activity_Object_Type::AUTO_POST, 'object_id' => (int) $created, 'object_label' => $library_data['title'], 'message' => 'Auto Post draft candidate saved to Library.', 'context' => array( 'auto_post_plan_library_item_id' => $draft->get_auto_post_plan_library_item_id(), 'field_mapping_library_item_id' => isset( $draft->to_array()['field_mapping_library_item_id'] ) ? (int) $draft->to_array()['field_mapping_library_item_id'] : 0, 'source_preview_library_item_id' => isset( $draft->to_array()['source_preview_library_item_id'] ) ? (int) $draft->to_array()['source_preview_library_item_id'] : 0, 'content_draft_library_item_id' => (int) $created, 'provider' => isset( $response_data['provider'] ) ? (string) $response_data['provider'] : '', 'model' => isset( $response_data['model'] ) ? (string) $response_data['model'] : '', 'request_id' => isset( $response_data['request_id'] ) ? (string) $response_data['request_id'] : '', 'has_output_json' => ! empty( $response_data['output_json'] ), 'has_output_text' => ! empty( $response_data['output_text'] ), 'default_status' => $draft->get_default_status(), 'generated_title_present' => '' !== $draft->get_title() ) ) ); return array( 'success' => true, 'library_item_id' => (int) $created, 'draft' => $draft, 'message_public' => 'Auto Post draft candidate saved to Library for review.' ); }
	public function validate_data( array $data ): array { return array( 'auto_post_plan_library_item_id' => isset( $data['auto_post_plan_library_item_id'] ) ? absint( $data['auto_post_plan_library_item_id'] ) : 0, 'additional_instructions' => isset( $data['additional_instructions'] ) ? sanitize_textarea_field( (string) $data['additional_instructions'] ) : '', 'source_label' => isset( $data['source_label'] ) ? sanitize_text_field( (string) $data['source_label'] ) : '', 'plan_title' => isset( $data['plan_title'] ) ? sanitize_text_field( (string) $data['plan_title'] ) : '' ); }
	public function extract_plan_payload( int $auto_post_plan_library_item_id ): array { $item = $this->library_repository->get( $auto_post_plan_library_item_id ); if ( ! $item ) { return array(); } $decoded = json_decode( $item->get_payload_redacted(), true ); return is_array( $decoded ) ? $decoded : array( 'summary' => $item->get_summary() ); }
	public function build_ai_task_data( array $data, array $plan_payload ): array { $field_mapping_id = isset( $plan_payload['field_mapping_library_item_id'] ) ? absint( $plan_payload['field_mapping_library_item_id'] ) : 0; $source_preview_id = isset( $plan_payload['source_preview_library_item_id'] ) ? absint( $plan_payload['source_preview_library_item_id'] ) : 0; return array( 'task_type' => AI_Task_Type::GENERATE_CONTENT_DRAFT, 'input' => array( 'auto_post_plan_summary' => isset( $plan_payload['source_summary'] ) ? (string) $plan_payload['source_summary'] : ( isset( $plan_payload['summary'] ) ? (string) $plan_payload['summary'] : '' ), 'auto_post_plan_redacted' => $plan_payload ), 'instructions' => '' !== $data['additional_instructions'] ? $data['additional_instructions'] : 'Generate a review-first content draft candidate from this Auto Post Plan. Save candidate content only; do not write WordPress posts or publish.', 'output_schema' => Structured_Output::CONTENT_DRAFT_V1, 'metadata' => array( 'source' => 'auto_post_draft_generator', 'auto_post_plan_library_item_id' => $data['auto_post_plan_library_item_id'] ), 'library_context' => array_filter( array( 'auto_post_plan_library_item_id' => $data['auto_post_plan_library_item_id'], 'field_mapping_library_item_id' => $field_mapping_id, 'source_preview_library_item_id' => $source_preview_id ) ) ); }
	public function build_auto_post_draft( AI_Response $response, array $data, array $plan_payload ): Auto_Post_Draft { $rd = $response->to_array(); $payload = $response->get_output_json(); if ( empty( $payload ) && '' !== $response->get_output_text() ) { $payload = array( 'content' => $response->get_output_text(), 'safety_notes' => array( 'Review generated draft before approval or write flow.' ) ); } return Auto_Post_Draft::from_ai_response_data( $payload, array( 'auto_post_plan_library_item_id' => $data['auto_post_plan_library_item_id'], 'field_mapping_library_item_id' => isset( $plan_payload['field_mapping_library_item_id'] ) ? absint( $plan_payload['field_mapping_library_item_id'] ) : 0, 'source_preview_library_item_id' => isset( $plan_payload['source_preview_library_item_id'] ) ? absint( $plan_payload['source_preview_library_item_id'] ) : 0, 'source_summary' => isset( $plan_payload['source_summary'] ) ? (string) $plan_payload['source_summary'] : '', 'provider' => $rd['provider'] ?? '', 'model' => $rd['model'] ?? '', 'request_id' => $rd['request_id'] ?? '' ) ); }
	public function build_library_data( Auto_Post_Draft $draft, array $data ): array { $label = ! empty( $data['source_label'] ) ? $data['source_label'] : ( ! empty( $data['plan_title'] ) ? $data['plan_title'] : 'Auto Post Plan' ); $title = '' !== $draft->get_title() ? $draft->get_title() : 'Draft Candidate: ' . $label; return array( 'title' => $title, 'type' => Library_Type::CONTENT_DRAFT, 'status' => Library_Status::NEEDS_REVIEW, 'source_label' => $label, 'summary' => $draft->summary(), 'content' => $this->readable_draft_content( $draft ), 'payload_redacted' => $this->draft_payload_redacted( $draft ), 'created_context' => 'auto_post_draft_generator' ); }
	public function draft_payload_redacted( Auto_Post_Draft $draft ): string { return wp_json_encode( $draft->to_array(), JSON_UNESCAPED_SLASHES ); }
	public function readable_draft_content( Auto_Post_Draft $draft ): string { $notes = $draft->get_safety_notes(); return "Auto Post Draft Candidate\n\nTitle: " . $draft->get_title() . "\nDefault status: " . $draft->get_default_status() . "\nExcerpt: " . $draft->get_excerpt() . "\nMeta title: " . $draft->get_meta_title() . "\nMeta description: " . $draft->get_meta_description() . "\nSlug suggestion: " . $draft->get_slug_suggestion() . "\n\nContent:\n" . $draft->get_content() . "\n\nSafety notes:\n- " . implode( "\n- ", $notes ); }
	private function fail( string $message, array $context ) { $this->logger->failed( Activity_Action::AUTO_POST_DRAFT_FAILED, array( 'object_type' => Activity_Object_Type::AUTO_POST, 'message' => $message, 'context' => $context ) ); return array( 'success' => false, 'message_public' => $message ); }
}
